class Solution:
    def ratesAt(self, maturities: List[float], rates: List[float], queries: List[float]) -> List[float]:
        t, y, n = maturities, rates, len(maturities)
        out = []
        for q in queries:
            if q <= t[0]:
                out.append(y[0])
            elif q >= t[-1]:
                out.append(y[-1])
            else:
                i = bisect.bisect_right(t, q) - 1          # t[i] <= q < t[i + 1]
                out.append(y[i] + (y[i + 1] - y[i]) * (q - t[i]) / (t[i + 1] - t[i]))
        return out

