class Solution {
public:
    vector<double> ratesAt(vector<double>& maturities, vector<double>& rates, vector<double>& queries) {
        auto& t = maturities; auto& y = rates;
        vector<double> out;
        out.reserve(queries.size());
        for (double q : queries) {
            if (q <= t.front()) { out.push_back(y.front()); continue; }
            if (q >= t.back()) { out.push_back(y.back()); continue; }
            int i = int(upper_bound(t.begin(), t.end(), q) - t.begin()) - 1;   // t[i] <= q < t[i + 1]
            out.push_back(y[i] + (y[i + 1] - y[i]) * (q - t[i]) / (t[i + 1] - t[i]));
        }
        return out;
    }
};

